alter table clients add column if not exists contact_phone text; create table if not exists public.enquiry_throttle ( id uuid primary key default gen_random_uuid(), ip_hash text not null, created_at timestamptz not null default now() ); create index if not exists enquiry_throttle_lookup on public.enquiry_throttle (ip_hash, created_at desc); alter table public.enquiry_throttle enable row level security; revoke all on public.enquiry_throttle from anon; revoke all on public.enquiry_throttle from authenticated;
